    pattern = r'const\s+\w+\s*=\s*React\.lazy\(\s*\(\)\s*=>\s*import\(\s*["\']\.\/Kit["\']\s*\)\.then\(\s*\(module\)\s*=>\s*\(\{\s*default:\s*module\.KitSection\s*\}\)\s*\)\s*\);'
