/**
 * [👤compose📚js🗃️sketchpad💻home🔖imports🔖app✂️hometoolbarcreate](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/App/d/i/HomeToolbarCreate)
 * KitKind holds the data fields for a KitKind record.
 **/
type KitKind = "temporary" | "local" | "remote";

/**
 * [👤compose📚js🗃️sketchpad💻home🔖app🪨hometoolbarfilters](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/d/i/HomeToolbarFilters)
 * HomeToolbarFilters holds the data fields for a HomeToolbarFilters record.
 **/
const HomeToolbarFilters: FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const availableKitKinds = useAvailableKitKinds();
  const selectedKind = searchParams.get("kind") as KitKind | null;

  const toggleKind = (type: KitKind) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedKind === type) {
      newParams.delete("kind");
      newParams.delete("name");
      newParams.delete("version");
    } else {
      newParams.set("kind", type);
      newParams.delete("name");
      newParams.delete("version");
    }
    setSearchParams(newParams);
  };

  const labelTemporary = useLabel("compose.sketchpad.app.home.toolbar.showTemporary");
  const labelLocal = useLabel("compose.sketchpad.app.home.toolbar.showLocal");
  const labelRemote = useLabel("compose.sketchpad.app.home.toolbar.showRemote");

  return (
    <ToolbarGroup>
      {availableKitKinds.temporary && <Toggle pressed={selectedKind === "temporary"} onPressedChange={() => toggleKind("temporary")} id="compose.sketchpad.app.home.toolbar.showTemporary" icon={<TemporaryKitIcon />} text={labelTemporary} />}
      {availableKitKinds.local && <Toggle pressed={selectedKind === "local"} onPressedChange={() => toggleKind("local")} id="compose.sketchpad.app.home.toolbar.showLocal" icon={<LocalKitIcon />} text={labelLocal} />}
      {availableKitKinds.remote && <Toggle pressed={selectedKind === "remote"} onPressedChange={() => toggleKind("remote")} id="compose.sketchpad.app.home.toolbar.showRemote" icon={<RemoteKitIcon />} text={labelRemote} />}
    </ToolbarGroup>
  );
};

/**
 * [👤compose📚js🗃️sketchpad💻home🔖app🪨hometoolbarcreate](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/d/i/HomeToolbarCreate)
 * HomeToolbarCreate holds the data fields for a HomeToolbarCreate record.
 **/
const HomeToolbarCreate: FC = () => {
  const kits = useKits();
  const availableKitKinds = useAvailableKitKinds();
  const defaultKitName = useLabel("compose.sketchpad.app.kit.defaultName");
  const { createKit, navigateToKit } = useSketchpadCommands();

  const handleCreateKit = useCallback(
    (type: KitKind) => {
      const existingNames = kits.map((kit) => kit.name);
      const uniqueName = generateUniqueName(defaultKitName ?? "", existingNames) ?? defaultKitName ?? "";
      const newKit: Kit = {
        guid: guid(),
        name: uniqueName,
        version: "",
        types: [],
        designs: [],
      };
      const local = type === "local" || type === "remote";
      const remote = type === "remote";
      createKit("compose.sketchpad.app.home.toolbar.createKit", newKit, local, remote);
      navigateToKit(newKit.guid);
    },
    [createKit, defaultKitName, kits, navigateToKit],
  );

  const labelTemporary = useLabel("compose.sketchpad.app.home.toolbar.createTemporary");
  const labelLocal = useLabel("compose.sketchpad.app.home.toolbar.createLocal");
  const labelRemote = useLabel("compose.sketchpad.app.home.toolbar.createRemote");

  return (
    <ToolbarGroup>
      {availableKitKinds.temporary && <Action id="compose.sketchpad.app.home.toolbar.createTemporary" icon={<TemporaryKitIcon />} text={labelTemporary} onClick={() => handleCreateKit("temporary")} />}
      {availableKitKinds.local && <Action id="compose.sketchpad.app.home.toolbar.createLocal" icon={<LocalKitIcon />} text={labelLocal} onClick={() => handleCreateKit("local")} />}
      {availableKitKinds.remote && <Action id="compose.sketchpad.app.home.toolbar.createRemote" icon={<RemoteKitIcon />} text={labelRemote} onClick={() => handleCreateKit("remote")} />}
    </ToolbarGroup>
  );
};

/**
 * TableRow holds the data fields for a TableRow record.
 * [👤compose📚js🗃️sketchpad💻home🔖imports🔖app✂️tablerow](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/App/d/i/TableRow)
 **/
type TableRow = {
  id: string;
  name: string;
  level: number;
  parentId?: string;
  hasChildren: boolean;
  isExpanded: boolean;
  type: KitKind | "docs" | "loading";
  updatedAt: string;
  createdAt: string;
  kit?: KitShallow;
  docsPath?: string;
  icon?: string;
  isLoading?: boolean;
  concepts?: string[];
};

/**
 * [👤compose📚js🗃️sketchpad💻home🔖app🪨hometablecontent](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/d/i/HomeTableContent)
 * HomeTableContent holds the data fields for a HomeTableContent record.
 **/
const HomeTableContent: FC = () => {
  const navigate = useNavigate();
  const navigation = useNavigation();
  const [searchParams, setSearchParams] = useSearchParams();
  const kits = useKits();
  const getKitKind = useGetKitKind();
  const { createKit, navigateToKit, getKitSnapshot } = useSketchpadCommands();

  const homeState = useHome() as any;
  const homeCommands = useHomeCommands();
  const isMobile = useIsMobile();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();
  const tooltip = useTooltip();

  const selection = homeState?.selection?.kits || [];
  const hover = useHomeHover();
  const lastClickedIdRef = React.useRef<string | null>(null);

  const defaultKitName = useLabel("compose.sketchpad.app.kit.defaultName");
  const newVersionLabel = useLabel("compose.sketchpad.app.kit.newVersion");
  const defaultVersionLabel = useLabel("compose.sketchpad.app.kit.defaultVersion");

  useEffect(() => {
    if (appType !== "home") return;

    const hasKits = selection.length > 0;
    const hasSingleKit = selection.length === 1;
    const hasMultipleKits = selection.length > 1;

    removeSection("details", "compose.sketchpad.app.kit.properties");
    removeSection("details", "compose.sketchpad.app.home.kits.multiple");

    if (hasKits) {
      const sectionId = hasSingleKit ? "compose.sketchpad.app.kit.properties" : "compose.sketchpad.app.home.kits.multiple";
      addSection("details", {
        id: sectionId,
        specificity: 0,
        order: 0,
        content: () => {
          return <HomeKitSection />;
        },
      });
    }

    return () => {
      removeSection("details", "compose.sketchpad.app.kit.properties");
      removeSection("details", "compose.sketchpad.app.home.kits.multiple");
    };
  }, [appType, addSection, removeSection, selection.length]);

  const selectedKind = searchParams.get("kind") as KitKind | null;
  const selectedName = searchParams.get("name");
  const selectedVersion = searchParams.get("version");

  const searchQuery = searchParams.get("q") || "";

  const expandedRowsParam = searchParams.getAll("e");
  const expandedRows = new Set(expandedRowsParam);

  const sortColumn = homeState?.sortColumn;
  const sortDirection = homeState?.sortDirection || "asc";

  const uniqueNames = useMemo(() => {
    const nameSet = new Set<string>();
    kits.forEach((kit) => {
      const type = getKitKind(kit.guid) || "temporary";

      if (selectedKind && selectedKind !== type) return;
      nameSet.add(kit.name);
    });
    return Array.from(nameSet).sort();
  }, [kits, getKitKind, selectedKind]);

  const uniqueVersions = useMemo(() => {
    if (!selectedName) return [];
    const versionSet = new Set<string>();
    kits.forEach((kit) => {
      if (kit.name === selectedName) {
        versionSet.add(kit.version || "");
      }
    });
    return Array.from(versionSet).sort();
  }, [kits, selectedName]);

  const allConcepts = useMemo(() => {
    const conceptSet = new Set<string>();
    kits.forEach((kitShallow) => {
      const fullKit = getKitSnapshot(kitShallow.guid);
      if (!fullKit) return;

      kitShallow.concepts?.forEach((conceptEntry) => {
        const conceptGuid = typeof conceptEntry === "string" ? conceptEntry : (conceptEntry as any).guid;
        const concept = fullKit.concepts?.find((c) => c.guid === conceptGuid);
        if (concept?.name) conceptSet.add(concept.name);
      });
    });
    return Array.from(conceptSet).sort();
  }, [kits, getKitSnapshot]);

  const selectedConcepts = useMemo(() => {
    const conceptsParam = searchParams.get("concepts");
    return conceptsParam ? conceptsParam.split(",").filter(Boolean) : [];
  }, [searchParams]);

  const rows = useMemo<TableRow[]>(() => {
    const result: TableRow[] = [];
    const locale = i18n.language === "de" ? de : enUS;
    const formatDate = (date?: Date | string) => {
      if (!date) return "";
      const parsedDate = date instanceof Date ? date : new Date(date);
      if (isNaN(parsedDate.getTime())) return "";
      return formatDistanceToNow(parsedDate, { addSuffix: true, locale });
    };

    const allDocsPages = docsRegistry.getAllPages();
    const allDocsSections = docsRegistry.getAllSections();

    const docsParentId = "docs-root";
    result.push({
      id: docsParentId,
      name: "Documentation",
      level: 0,
      hasChildren: true,
      isExpanded: expandedRows.has(docsParentId),
      type: "docs",
      updatedAt: "",
      createdAt: "",
      kit: undefined,
      docsPath: undefined,
    });

    if (expandedRows.has(docsParentId)) {
      allDocsSections.forEach((section) => {
        const sectionId = `docs-section-${section.id}`;
        const sectionPages = docsRegistry.getPagesBySection(section.id);

        result.push({
          id: sectionId,
          name: section.label,
          level: 1,
          parentId: docsParentId,
          hasChildren: sectionPages.length > 0,
          isExpanded: expandedRows.has(sectionId),
          type: "docs",
          updatedAt: "",
          createdAt: "",
          kit: undefined,
          docsPath: undefined,
          icon: section.icon,
        });

        if (expandedRows.has(sectionId)) {
          sectionPages.forEach((page) => {
            result.push({
              id: `docs-page-${page.path}`,
              name: page.title,
              level: 2,
              parentId: sectionId,
              hasChildren: false,
              isExpanded: false,
              type: "docs",
              updatedAt: "",
              createdAt: "",
              kit: undefined,
              docsPath: page.path,
              icon: page.icon,
            });
          });
        }
      });
    }

    const loadingKits = homeState?.loadingKits || [];
    loadingKits.forEach((loadingKit: LoadingKit) => {
      result.push({
        id: `loading-${loadingKit.tempGuid}`,
        name: loadingKit.name,
        level: 0,
        hasChildren: false,
        isExpanded: false,
        type: "loading",
        updatedAt: "",
        createdAt: "",
        kit: undefined,
        isLoading: true,
      });
    });

    const kitGroups = new Map<string, KitShallow[]>();

    kits.forEach((kit) => {
      const type = getKitKind(kit.guid) || "temporary";

      if (selectedKind && selectedKind !== type) return;
      if (searchQuery && !kit.name.toLowerCase().includes(searchQuery.toLowerCase())) return;
      if (selectedName && kit.name !== selectedName) return;
      if (selectedVersion && (kit.version || "") !== selectedVersion) return;

      if (selectedConcepts.length > 0) {
        const fullKit = getKitSnapshot(kit.guid);
        if (!fullKit) return;
        const kitConceptNames =
          kit.concepts
            ?.map((conceptEntry) => {
              const conceptGuid = typeof conceptEntry === "string" ? conceptEntry : (conceptEntry as any).guid;
              return fullKit.concepts?.find((c) => c.guid === conceptGuid)?.name;
            })
            .filter((name): name is string => name !== undefined) || [];

        if (!kitConceptNames.some((name) => selectedConcepts.includes(name))) return;
      }

      const key = kit.name;
      if (!kitGroups.has(key)) kitGroups.set(key, []);
      kitGroups.get(key)!.push(kit);
    });

    const resolveKitConcepts = (kit: KitShallow): string[] => {
      const fullKit = getKitSnapshot(kit.guid);
      if (!fullKit) return [];
      return (
        kit.concepts
          ?.map((conceptEntry) => {
            const conceptGuid = typeof conceptEntry === "string" ? conceptEntry : (conceptEntry as any).guid;
            return fullKit.concepts?.find((c) => c.guid === conceptGuid)?.name;
          })
          .filter((name): name is string => name !== undefined) || []
      );
    };

    kitGroups.forEach((groupKits, name) => {
      const parentId = `kit-${name}`;
      const defaultKit = groupKits.find((k) => !k.version);
      const parentKit = defaultKit || groupKits[0];
      const hasChildren = groupKits.some((k) => k.guid !== parentKit.guid);

      const type = getKitKind(parentKit.guid) || "temporary";

      result.push({
        id: parentId,
        name: name,
        level: 0,
        hasChildren,
        isExpanded: expandedRows.has(parentId),
        type,
        updatedAt: formatDate(parentKit.updatedAt),
        createdAt: formatDate(parentKit.createdAt),
        kit: parentKit,
        concepts: resolveKitConcepts(parentKit),
      });

      if (expandedRows.has(parentId) && hasChildren) {
        groupKits.forEach((kit) => {
          if (kit.guid === parentKit.guid) return;
          const kitKind = getKitKind(kit.guid) || "temporary";

          const versionId = `${parentId}-${kit.version || "default"}`;
          result.push({
            id: versionId,
            name: kit.version || "(default)",
            level: 1,
            parentId,
            hasChildren: false,
            isExpanded: false,
            type: kitKind,
            updatedAt: formatDate(kit.updatedAt),
            createdAt: formatDate(kit.createdAt),
            kit: kit,
            concepts: resolveKitConcepts(kit),
          });
        });
      }
    });

    if (sortColumn) {
      const topLevelRows = result.filter((r) => r.level === 0);
      const childRows = result.filter((r) => r.level > 0);
      topLevelRows.sort((a, b) => {
        let comparison = 0;
        switch (sortColumn) {
          case "name":
            comparison = a.name.localeCompare(b.name);
            break;
          case "type":
            comparison = a.type.localeCompare(b.type);
            break;
          case "updatedAt":
            comparison = a.updatedAt.localeCompare(b.updatedAt);
            break;
          case "createdAt":
            comparison = a.createdAt.localeCompare(b.createdAt);
            break;
        }
        return sortDirection === "asc" ? comparison : -comparison;
      });
      const sortedResult: TableRow[] = [];
      topLevelRows.forEach((parent) => {
        sortedResult.push(parent);
        const children = childRows.filter((c) => c.parentId === parent.id);
        children.sort((a, b) => {
          let comparison = 0;
          switch (sortColumn) {
            case "name":
              comparison = a.name.localeCompare(b.name);
              break;
            case "type":
              comparison = a.type.localeCompare(b.type);
              break;
            case "updatedAt":
              comparison = a.updatedAt.localeCompare(b.updatedAt);
              break;
            case "createdAt":
              comparison = a.createdAt.localeCompare(b.createdAt);
              break;
          }
          return sortDirection === "asc" ? comparison : -comparison;
        });
        sortedResult.push(...children);
      });
      return sortedResult;
    }

    return result;
  }, [kits, getKitKind, selectedKind, searchQuery, selectedName, selectedVersion, expandedRows, sortColumn, sortDirection, homeState?.loadingKits]);

  const { setFocusItems, setOnFocusItem } = useFocus();
  const [focusedItemId, setFocusedItemId] = useState<string | undefined>();
  const prevRowsRef = useRef<string>("");

  useEffect(() => {
    const items = rows.map((row) => ({
      id: row.id,
      label: row.name,
      category: row.level === 0 ? "Kits" : "Versions",
    }));

    const itemsKey = items.map((item) => `${item.id}:${item.label}`).join("|");
    if (prevRowsRef.current !== itemsKey) {
      prevRowsRef.current = itemsKey;
      setFocusItems(items);
    }
  }, [rows, setFocusItems]);

  useEffect(() => {
    const handleFocus = (itemId: string) => {
      setFocusedItemId(itemId);
    };
    setOnFocusItem(handleFocus);
    return () => setOnFocusItem(undefined);
  }, [setOnFocusItem]);

  const handleCreateKit = (type: KitKind) => {
    const existingNames = kits.map((k) => k.name);
    const uniqueName = generateUniqueName(defaultKitName ?? "", existingNames) ?? defaultKitName ?? "";
    const newKit: Kit = {
      guid: guid(),
      name: uniqueName,
      version: "",
      types: [],
      designs: [],
    };
    const local = type === "local" || type === "remote";
    const remote = type === "remote";
    createKit("compose.sketchpad.app.home.canvas.table.createKit", newKit, local, remote);
    navigateToKit(newKit.guid);
  };

  const handleCreateVersion = (kitName: string, type: KitKind) => {
    const existingVersions = kits.filter((k) => k.name === kitName).map((k) => k.version || "");
    const uniqueVersion = generateUniqueName(newVersionLabel ?? "", existingVersions) ?? newVersionLabel ?? "";
    const newKit: Kit = {
      guid: guid(),
      name: kitName,
      version: uniqueVersion,
      types: [],
      designs: [],
    };
    const local = type === "local" || type === "remote";
    const remote = type === "remote";
    createKit("compose.sketchpad.app.home.canvas.table.createVersion", newKit, local, remote);
    navigateToKit(newKit.guid);
  };

  const toggleKind = (type: KitKind) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedKind === type) {
      newParams.delete("kind");
      newParams.delete("name");
      newParams.delete("version");
    } else {
      newParams.set("kind", type);
      newParams.delete("name");
      newParams.delete("version");
    }
    setSearchParams(newParams);
  };

  useHotkeys("compose.sketchpad.app.home.filter.kind.temporary", () => toggleKind("temporary"));
  useHotkeys("compose.sketchpad.app.home.filter.kind.local", () => toggleKind("local"));
  useHotkeys("compose.sketchpad.app.home.filter.kind.remote", () => toggleKind("remote"));

  const toggleName = (name: string) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedName === name) {
      newParams.delete("name");
      newParams.delete("version");
    } else {
      newParams.set("name", name);
      newParams.delete("version");
    }
    setSearchParams(newParams);
  };

  const toggleVersion = (version: string) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedVersion === version) {
      newParams.delete("version");
    } else {
      newParams.set("version", version);
    }
    setSearchParams(newParams);
  };

  const toggleConcept = (concept: string) => {
    const newParams = new URLSearchParams(searchParams);
    const currentConcepts = newParams.get("concepts")?.split(",").filter(Boolean) || [];
    if (currentConcepts.includes(concept)) {
      const updated = currentConcepts.filter((c) => c !== concept);
      if (updated.length > 0) {
        newParams.set("concepts", updated.join(","));
      } else {
        newParams.delete("concepts");
      }
    } else {
      newParams.set("concepts", [...currentConcepts, concept].join(","));
    }
    setSearchParams(newParams);
  };

  const toggleRow = (rowId: string) => {
    const currentUrl = new URL(window.location.href);
    const currentRows = currentUrl.searchParams.getAll("e");

    if (currentRows.includes(rowId)) {
      currentUrl.searchParams.delete("e");
      currentRows.filter((r) => r !== rowId).forEach((r) => currentUrl.searchParams.append("e", r));
    } else {
      currentUrl.searchParams.append("e", rowId);
    }

    window.history.replaceState(window.history.state, "", currentUrl);

    window.dispatchEvent(new PopStateEvent("popstate", { state: window.history.state }));
  };

  const handleSearchChange = (value: string) => {
    const newParams = new URLSearchParams(searchParams);
    if (value) {
      newParams.set("q", value);
    } else {
      newParams.delete("q");
    }
    setSearchParams(newParams);
  };

  const handleRowClick = (kitId: string, e: React.MouseEvent) => {
    const compositionKind = resolveSelectionCompositionKind(ToolKind.SELECTION_NORMAL, {
      shiftKey: e.shiftKey,
      altKey: e.altKey,
      ctrlKey: e.ctrlKey,
      metaKey: e.metaKey,
    });
    const useRangeSelection = e.shiftKey && !e.altKey && !e.ctrlKey && !e.metaKey;
    if (useRangeSelection && lastClickedIdRef.current) {
      const currentIndex = rows.findIndex((r) => r.kit?.guid === kitId);
      const lastIndex = rows.findIndex((r) => r.kit?.guid === lastClickedIdRef.current);
      if (lastIndex !== -1 && currentIndex !== -1) {
        const start = Math.min(lastIndex, currentIndex);
        const end = Math.max(lastIndex, currentIndex);
        const rangeIds = rows
          .slice(start, end + 1)
          .map((r) => r.kit?.guid)
          .filter((id): id is string => id !== undefined);
        const newSelection = applySelectionComposition(selection, rangeIds, compositionKind);
        homeCommands.clearSelection();
        for (const id of newSelection) {
          homeCommands.addKitToSelection("compose.sketchpad.app.home.canvas.table.selectKitsRange", id);
        }
      }
    } else {
      const newSelection = applySelectionComposition(selection, [kitId], compositionKind);
      homeCommands.clearSelection();
      for (const id of newSelection) {
        homeCommands.addKitToSelection("compose.sketchpad.app.home.canvas.table.selectKit", id);
      }
      lastClickedIdRef.current = kitId;
    }
  };

  const handleSortClick = (column: "name" | "type" | "updatedAt" | "createdAt") => {
    homeCommands.toggleSort("compose.sketchpad.app.home.canvas.table.toggleSort", column);
  };

  if (isMobile) {
    return (
      <div
        className="flex flex-col h-full"
        onClick={(e: React.MouseEvent) => {
          if (e.target === e.currentTarget) {
            homeCommands.deselectAll("compose.sketchpad.app.home.canvas.table.deselect");
          }
        }}
      >
        <div className="flex items-center justify-between border-b border-element px-single h-large">
          <span className="font-medium">{useLabel("compose.sketchpad.app.home.name")}</span>
          <Toggle
            kind="dropdown"
            pressed={sortColumn === "name"}
            value={sortColumn === "name" ? sortDirection : "asc"}
            onValueChange={(value) => {
              homeCommands.setSortColumn("compose.sketchpad.app.home.filter.name.sortColumn", "name");
              homeCommands.setSortDirection("compose.sketchpad.app.home.header.name.sortDirection", value as "asc" | "desc");
            }}
            items={[
              { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
              { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
            ]}
            id={"compose.sketchpad.app.home.sortByName"}
          />
        </div>
        <Scrollable className="flex-1">
          <div className="flex flex-col">
            {rows.map((row) => {
              const isSelected = row.kit ? selection.includes(row.kit.guid) : false;
              const isDocsRow = row.type === "docs";
              const isLoadingRow = row.isLoading;
              const isHovered = row.kit ? hover?.kits?.includes(row.kit.guid) : false;
              return (
                <div
                  key={row.id}
                  data-testid={`home-kit-row-${row.id}`}
                  data-loading={isLoadingRow ? "true" : "false"}
                  className={`border-b border-element p-single cursor-selectable h-medium ${isLoadingRow ? "opacity-50 pointer-events-none" : ""} ${isSelected ? "bg-active-base text-active-foreground" : isHovered ? "bg-hover-base" : "hover:bg-hover-base"}`}
                  role="button"
                  tabIndex={isLoadingRow ? -1 : 0}
                  onClick={(e) => {
                    if (isLoadingRow) return;
                    if (isDocsRow && row.docsPath) {
                      navigate(`/${row.docsPath}`);
                    } else if (row.kit) {
                      handleRowClick(row.kit.guid, e);
                    }
                  }}
                  onDoubleClick={() => {
                    if (isLoadingRow) return;
                    if (isDocsRow && row.docsPath) {
                      navigate(`/${row.docsPath}`);
                    } else if (row.kit) {
                      navigateToKit(row.kit.guid);
                    }
                  }}
                  onMouseEnter={() => {
                    if (!row.kit) {
                      homeCommands.clearHover("compose.sketchpad.app.home.canvas.table.clearHover");
                      return;
                    }
                    homeCommands.hoverKit("compose.sketchpad.app.home.canvas.table.hover", row.kit.guid);
                  }}
                  onMouseLeave={() => {
                    homeCommands.clearHover("compose.sketchpad.app.home.canvas.table.clearHover");
                  }}
                >
                  <div className="flex items-center gap-single w-full" onClick={(e) => e.stopPropagation()}>
                    <div className="flex items-center gap-single flex-1 min-w-0" style={{ paddingLeft: `calc(${row.level} * var(--size-small))` }}>
                      {row.hasChildren ? (
                        <Action
                          id={"compose.sketchpad.app.home.toggleRow"}
                          onClick={(e) => {
                            e.stopPropagation();
                            toggleRow(row.id);
                          }}
                          icon={row.isExpanded ? <ChevronDownIcon className="size-small" /> : <ChevronRightIcon className="size-small" />}
                        />
                      ) : (
                        <span className="size-small shrink-0" />
                      )}
                      <TableAvatar name={row.name} icon={row.kit?.icon} />
                      <span className="text-left flex-1 min-w-0 truncate">{row.name}</span>
                      {isLoadingRow && <Spinner size="small" />}
                    </div>
                    {row.concepts && row.concepts.length > 0 && (
                      <Scrollable orientation="horizontal" className="shrink-0 min-w-0 max-w-[200px]">
                        <div className="flex items-center gap-single px-single h-medium w-fit">
                          {row.concepts.map((concept) => (
                            <Action key={concept} onClick={() => toggleConcept(concept)} id={`compose.sketchpad.app.home.row.concept.${concept}`} text={concept} className={selectedConcepts.includes(concept) ? "bg-active-base" : ""} />
                          ))}
                        </div>
                      </Scrollable>
                    )}
                    <div className="flex items-center gap-single shrink-0 ml-auto">
                      {row.level === 0 && row.type !== "docs" && row.type !== "loading" && (
                        <Action
                          onClick={(e) => {
                            e.stopPropagation();
                            handleCreateVersion(row.name, row.type as KitKind);
                          }}
                          id={"compose.sketchpad.app.home.createVersion"}
                          icon={<AddIcon />}
                        />
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </Scrollable>
      </div>
    );
  }

  return (
    <div
      className="flex flex-col h-full"
      onClick={(e: React.MouseEvent) => {
        if (e.target === e.currentTarget) {
          homeCommands.deselectAll("compose.sketchpad.app.home.canvas.table.deselect");
        }
      }}
    >
      <Table<TableRow>
        className="flex-1 min-h-0"
        columns={[
          ...(!selectedKind
            ? [
                {
                  id: "type",
                  header: (
                    <div className="inline-flex items-center gap-single">
                      <span>{useLabel("compose.sketchpad.app.home.kind")}</span>
                      <Toggle
                        kind="dropdown"
                        pressed={sortColumn === "type"}
                        value={sortColumn === "type" ? sortDirection : "asc"}
                        onValueChange={(value) => {
                          homeCommands.setSortColumn("compose.sketchpad.app.home.header.type.sortColumn", "type");
                          homeCommands.setSortDirection("compose.sketchpad.app.home.header.type.sortDirection", value as "asc" | "desc");
                        }}
                        items={[
                          { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                          { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                        ]}
                        id={"compose.sketchpad.app.home.sortByType"}
                      />
                    </div>
                  ),
                  accessor: (row) => (
                    <>
                      {row.type === "temporary" && <TemporaryKitIcon />}
                      {row.type === "local" && <LocalKitIcon />}
                      {row.type === "remote" && <RemoteKitIcon />}
                      {row.type === "docs" && <DocumentIcon className="size-small" />}
                    </>
                  ),
                  width: "w-0 whitespace-nowrap",
                  headerClassName: "relative group w-0 whitespace-nowrap",
                } as TableColumn<TableRow>,
              ]
            : []),
          {
            id: "name",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("compose.sketchpad.app.home.name")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "name"}
                  value={sortColumn === "name" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("compose.sketchpad.app.home.header.name.sortColumn", "name");
                    homeCommands.setSortDirection("compose.sketchpad.app.home.header.name.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                  ]}
                  id={"compose.sketchpad.app.home.sortByName"}
                />
              </div>
            ),
            accessor: (row) => (
              <div className={`flex items-center gap-single w-full ${row.isLoading ? "opacity-50 pointer-events-none" : ""}`} onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center gap-single flex-1 min-w-0" style={{ paddingLeft: `calc(${row.level} * var(--size-small))` }}>
                  {row.hasChildren ? (
                    <Action
                      id={"compose.sketchpad.app.home.toggleRow"}
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleRow(row.id);
                      }}
                      icon={row.isExpanded ? <ChevronDownIcon className="size-small" /> : <ChevronRightIcon className="size-small" />}
                    />
                  ) : (
                    <span className="size-small shrink-0" />
                  )}
                  <TableAvatar name={row.name} icon={row.type === "docs" ? row.icon : row.kit?.icon} />
                  <span className="text-left min-w-0 truncate">{row.name}</span>
                  {row.isLoading && <Spinner size="small" />}
                </div>
                {row.concepts && row.concepts.length > 0 && (
                  <Scrollable orientation="horizontal" className="shrink-0 min-w-0 max-w-[200px]">
                    <div className="flex items-center gap-single px-single h-medium w-fit">
                      {row.concepts.map((concept) => (
                        <Action key={concept} onClick={() => toggleConcept(concept)} id={`compose.sketchpad.app.home.row.concept.${concept}`} text={concept} className={selectedConcepts.includes(concept) ? "bg-active-base" : ""} />
                      ))}
                    </div>
                  </Scrollable>
                )}
                <div className="flex items-center gap-single shrink-0 ml-auto">
                  {row.level === 0 && row.type !== "docs" && row.type !== "loading" && (
                    <Action
                      onClick={(e) => {
                        e.stopPropagation();
                        handleCreateVersion(row.name, row.type as KitKind);
                      }}
                      id={"compose.sketchpad.app.home.createVersion"}
                      icon={<AddIcon />}
                    />
                  )}
                </div>
              </div>
            ),
            headerClassName: "relative group",
          },
          {
            id: "updatedAt",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("compose.sketchpad.app.home.lastUpdated")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "updatedAt"}
                  value={sortColumn === "updatedAt" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("compose.sketchpad.app.home.header.updatedAt.sortColumn", "updatedAt");
                    homeCommands.setSortDirection("compose.sketchpad.app.home.header.updatedAt.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                  ]}
                  id={"compose.sketchpad.app.home.sortByUpdatedAt"}
                />
              </div>
            ),
            accessor: (row) => row.updatedAt,
            headerClassName: "relative group",
          },
          {
            id: "createdAt",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("compose.sketchpad.app.home.created")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "createdAt"}
                  value={sortColumn === "createdAt" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("compose.sketchpad.app.home.header.createdAt.sortColumn", "createdAt");
                    homeCommands.setSortDirection("compose.sketchpad.app.home.header.createdAt.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                  ]}
                  id={"compose.sketchpad.app.home.sortByCreatedAt"}
                />
              </div>
            ),
            accessor: (row) => row.createdAt,
            headerClassName: "relative group",
          },
        ]}
        rowClassName={(row) => {
          if (!row.kit) return "";
          if (selection.includes(row.kit.guid)) return "";
          return hover?.kits?.includes(row.kit.guid) ? "bg-hover-base" : "";
        }}
        onRowMouseEnter={(row) => {
          if (!row.kit) {
            homeCommands.clearHover("compose.sketchpad.app.home.canvas.table.clearHover");
            return;
          }
          homeCommands.hoverKit("compose.sketchpad.app.home.canvas.table.hover", row.kit.guid);
        }}
        onRowMouseLeave={() => {
          homeCommands.clearHover("compose.sketchpad.app.home.canvas.table.clearHover");
        }}
        data={rows}
        onRowClick={(row, _, e) => {
          const isDocsRow = row.type === "docs";
          if (isDocsRow && row.docsPath) {
            navigate(`/${row.docsPath}`);
          } else if (row.kit) {
            handleRowClick(row.kit.guid, e);
          }
        }}
        onRowDoubleClick={(row) => {
          const isDocsRow = row.type === "docs";
          if (isDocsRow && row.docsPath) {
            navigate(`/${row.docsPath}`);
          } else if (row.kit) {
            navigateToKit(row.kit.guid);
          }
        }}
        rowKey={(row) => row.id}
        getRowId={(row) => row.kit?.guid || row.id}
        selectedRows={new Set(selection)}
        focusedItemId={focusedItemId}
        onFocusComplete={() => setFocusedItemId(undefined)}
        emptyMessage={useLabel("compose.sketchpad.app.home.noKits")}
        stickyHeader={true}
        headerClassName="sticky top-0 border-b border-element"
        hierarchical={true}
      />
    </div>
  );
};

// #region Multi-Window App

// [👤compose📚js🗃️sketchpad💻hometsx🔖app🔖multiwindowapp](repo://section/COMPOSE/JS/SKETCHPAD/HOME.TSX/APP/MULTI-WINDOW-APP)
// Multi-window app MUST orchestrate the Home canvas and layout.

/**
 * [👤compose📚js🗃️sketchpad💻home🔖imports🔖app🔖multiwindowapp🪨home](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/App/s/Multi-Window%20App/d/i/Home)
 * TableWindow holds the data fields for a TableWindow record.
 **/
const TableWindow = memo(() => {
  return <HomeTableContent />;
});
TableWindow.displayName = "TableWindow";

/**
 * [👤compose📚js🗃️sketchpad💻home🔖app🔖multiwindowapp🪨home](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/s/Multi-Window%20App/d/i/Home)
 * Home holds the data fields for a Home record.
 **/
const Home: FC = () => {
  const actor = useSketchpadActor();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();
  const isMobile = useIsMobile();
  const availableKitKinds = useAvailableKitKinds();

  const homeState = useHome() as HomeState;
  const storedWindowLayout = homeState?.windowLayout;

  const lastLayoutRef = useRef<any>(null);

  useEffect(() => {
    if (appType !== "home") return;

    const hasAvailableKitKinds = availableKitKinds.temporary || availableKitKinds.local || availableKitKinds.remote;

    if (hasAvailableKitKinds) {
      addSection("toolbar", {
        id: "compose.sketchpad.app.home.toolbar.filters",
        specificity: 20,
        order: 0,
        toolbarGroup: {
          id: "filter",
          labelId: "compose.sketchpad.toolbar.parent.filter",
          order: 20,
        },
        content: <HomeToolbarFilters />,
      });
      addSection("toolbar", {
        id: "compose.sketchpad.app.home.toolbar.create",
        specificity: 20,
        order: 0,
        toolbarGroup: {
          id: "create",
          labelId: "compose.sketchpad.toolbar.parent.create",
          order: 30,
        },
        content: <HomeToolbarCreate />,
      });
    }

    return () => {
      removeSection("toolbar", "compose.sketchpad.app.home.toolbar.filters");
      removeSection("toolbar", "compose.sketchpad.app.home.toolbar.create");
    };
  }, [appType, addSection, removeSection, availableKitKinds]);

  // Add Settings and Chat as side panel tabs
  const addSidePanelTab = useAddSidePanelTab();
  const removeSidePanelTab = useRemoveSidePanelTab();

  useEffect(() => {
    if (appType !== "home") return;

    addSidePanelTab("right", {
      id: "compose.sketchpad.app.home.settings",
      icon: SettingsIcon,
      order: 100,
      content: () => (
        <TreeStateProvider>
          <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "compose.sketchpad.app.home.settings.content", label: null, content: <SettingsContent /> }]} />
        </TreeStateProvider>
      ),
    });

    addSidePanelTab("right", {
      id: "compose.sketchpad.app.home.chat",
      icon: ChatIcon,
      order: 101,
      content: () => (
        <TreeStateProvider>
          <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "compose.sketchpad.app.home.chat.content", label: null, content: <ChatPlaceholder /> }]} />
        </TreeStateProvider>
      ),
    });

    return () => {
      removeSidePanelTab("right", "compose.sketchpad.app.home.settings");
      removeSidePanelTab("right", "compose.sketchpad.app.home.chat");
    };
  }, [appType, addSidePanelTab, removeSidePanelTab]);

  const defaultLayout = useMemo(
    () => ({
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "100%",
            content: [
              {
                type: "component",
                componentName: HomeAppWindowKind.Table,
                title: "table",
                componentState: {},
              },
            ],
          },
        ],
      },
    }),
    [],
  );

  const windowLayout = useMemo(() => storedWindowLayout || defaultLayout, [storedWindowLayout, defaultLayout]);

  const windowConfig: AppWindowConfig = useMemo(
    () => ({
      windowKinds: [
        {
          id: HomeAppWindowKind.Table,
          label: "table",
          component: () => <TableWindow />,
        },
      ],
      defaultLayout,
    }),
    [defaultLayout],
  );

  const handleLayoutChange = useCallback(
    (config: any) => {
      const configStr = JSON.stringify(config);
      const lastStr = JSON.stringify(lastLayoutRef.current);
      if (configStr === lastStr) return;
    },
    [actor],
  );

  if (isMobile) {
    return (
      <HomeDropZone>
        <HomeTableContent />
      </HomeDropZone>
    );
  }

  return (
    <>
      <HomeFooter />
      <HomeDropZone>
        <Canvas id="compose.sketchpad.app.home.canvas">
          <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
        </Canvas>
      </HomeDropZone>
    </>
  );
};

