// #region Config

// [👤compose📚js🗃️sketchpad💻hometsx🔖config](repo://section/COMPOSE/JS/SKETCHPAD/HOME.TSX/CONFIG)
// Config MUST define the Home app registration and panel setup.

/**
 * Home app configuration defining routes and panels.
 * [👤compose📚js🗃️sketchpad💻home🔖imports🔖config🪨config](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Config/d/i/config)
 **/
export const homeConfig: AppConfig = {
  id: "home",
  component: Home,
  routeSegments: [],
  additionalPaths: ["kits"],
  getPanels: (): PanelDefinition[] => [createPanelDefinition(PanelKind.TOOLBAR, "compose.sketchpad.navbar.panelToggle.toolbar.show"), createPanelDefinition(PanelKind.DETAILS, "compose.sketchpad.navbar.panelToggle.details.show")],
  matchesPath: (pathParts) => pathParts.length === 0 || (pathParts.length === 1 && pathParts[0] === "kits"),
  order: 0,
