        <CheckIcon className="size-small" />
        {submitLabel}
      </Button>
    </ToolbarGroup>
  );
};

/**
 * [👤compose📚js🗃️sketchpad💻feedback🔖app🪨feedback](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Feedback.tsx/s/App/d/i/Feedback)
 * Feedback holds the data fields for a Feedback record.
 **/
const Feedback: FC = () => {
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();

  useLayoutEffect(() => {
    if (appType !== "feedback") return;

    addSection("toolbar", {
      id: "compose.sketchpad.app.feedback.toolbar.send",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "actions",
        labelId: "compose.sketchpad.toolbar.parent.actions",
        order: 50,
      },
      content: <FeedbackToolbar />,
    });

    return () => {
      removeSection("toolbar", "compose.sketchpad.app.feedback.toolbar.send");
    };
  }, [appType, addSection, removeSection]);

  return (
    <Canvas>
      <FeedbackForm />
    </Canvas>
  );
};


