    m = re.match(r'^(?:export\s+)?class\s+(\w+)', s)
    if m:
        name = m.group(1)
        if name not in class_defs:
            class_defs[name] = i + 1

    # Top-level const (rough: only if starts at beginning of line)
    if not s.startswith('//') and not s.startswith('*') and not s.startswith('/**'):
        m = re.match(r'^(?:export\s+)?const\s+(\w+)', s)
        if m:
            name = m.group(1)
            if name not in const_defs:
                const_defs[name] = i + 1

# Now check class names used before their definition
print("Classes used before definition:")
for name, def_line in sorted(class_defs.items()):
    for i, line in enumerate(lines):
